void main() {
    int amount = 19999;
    int limit = 20000;
    // 배송비는 아래 두 경로 중 한 곳에서 정해요.
    int fee;
    if (amount >= limit) {
        fee = 0;
    } else {
        fee = 3000;
    }
    // 이 주석 위의 if에 else를 이어 붙여 나머지 경우 fee를 3000으로 정하세요.
    System.out.println(fee);
}

